import osimport redef GiaToc(ID_SKIN, ID_HD, NAME_HERO, ID_HERO, hasteE1_Mod, HasteE1_leave_Mod, DaofengSprint_Mod, xyz_GIATOC, code_duoi_giatoc):    if ID_SKIN in ["19908", "53806", "15015", "13314"]:        FILES = [hasteE1_Mod]    else:                FILES = [hasteE1_Mod, HasteE1_leave_Mod]                    for file in FILES:        GuidStopTrack = b'412ea073-5944-46e4-ae5e-3037e855fda7'                if file == hasteE1_Mod:            GuidStopTrack2 = b'aecced31-0011-43e4-a7f2-14f999d326b3'            elif file == HasteE1_leave_Mod:            GuidStopTrack2 = b'19961cb1-9834-423d-9e7f-de15b90824fd'                if ID_SKIN == "53806":            code_duoi_giatoc = b"Iggy_sprint"            xyz_GIATOC = b'x="0.000" y="-0.150" z="0.000"'                    if ID_SKIN == "19908":            xyz_GIATOC = b'x="0.000" y="-0.150" z="0.000"'                    if ID_SKIN == "15004":            code_duoi_giatoc = b"jiashu_01"            xyz_GIATOC = b'x="0.000" y="0.800" z="-0.500"'        with open('Data/Code/CODE_GT2.xml', 'rb') as f:            code_gt1 = f.read()        code_gt_tong = code_gt1                if ID_SKIN in ["13311"]:            xyz_GIATOC = b'x="0.000" y="0.800" z="-0.500"'            code_gt_tong = code_gt_tong.replace(b'Prefab_Skill_Effects/Hero_Skill_Effects/NAME_HERO/ID_SKIN/code_duoi_giatoc', b'Prefab_Skill_Effects/Inner_Game_Effect/sprint/sprint_122_gushiji')                if code_duoi_giatoc != b'jiasu_tongyong_01':            code_gt_tong = code_gt_tong.replace(b'ID_SKIN', ID_SKIN.encode()).replace(b'ID_HERO', ID_HERO.encode()).replace(b'NAME_HERO', NAME_HERO.encode()).replace(b'x="0.000" y="0.000" z="0.000"', xyz_GIATOC).replace(b'code_duoi_giatoc', code_duoi_giatoc).replace(b'GuidStopTrack1', GuidStopTrack).replace(b'GuidStopTrack2', GuidStopTrack2)        else:            code_gt_tong = code_gt_tong.replace(b'ID_SKIN', ID_SKIN.encode()).replace(b'ID_HERO', ID_HERO.encode()).replace(b'NAME_HERO', NAME_HERO.encode()).replace(b'x="0.000" y="0.000" z="0.000"', xyz_GIATOC).replace(b'code_duoi_giatoc', code_duoi_giatoc).replace(b'GuidStopTrack1', GuidStopTrack).replace(b'GuidStopTrack2', GuidStopTrack2)                    if ID_SKIN == "15710":            with open('Data/Code/CODE_GT2.xml', 'rb') as f:                code_gt2 = f.read()            code_gt_tong2 = code_gt2            code_gt_tong2 = code_gt_tong2.replace(b'ID_SKIN', ID_SKIN.encode()).replace(b'ID_HERO', ID_HERO.encode()).replace(b'NAME_HERO', NAME_HERO.encode()).replace(b'x="0.000" y="0.000" z="0.000"', xyz_GIATOC).replace(b'code_duoi_giatoc', code_duoi_giatoc).replace(b'jiasu_tongyong_01', b'jiasu_tongyong_02').replace(b'GuidStopTrack1', GuidStopTrack).replace(b'GuidStopTrack2', GuidStopTrack2)                  with open(file, 'rb') as f:                code_gt = f.read().replace(b'  </Action>\r\n</Project>', code_gt_tong).replace(b'  </Action>\r\n</Project>', code_gt_tong2)            with open(file, 'wb') as f:                f.write(code_gt)                        if ID_SKIN == "15015":            with open('Data/Code/CODE_GT_15015.xml', 'rb') as f:                                code_gt1 = f.read()            code_gt_tong = code_gt1            code_gt_tong = code_gt_tong.replace(b'ID_SKIN', ID_SKIN.encode()).replace(b'ID_HERO', ID_HERO.encode()).replace(b'NAME_HERO', NAME_HERO.encode()).replace(b'GuidStopTrack1', GuidStopTrack).replace(b'GuidStopTrack2', GuidStopTrack2)            with open(file, 'rb') as f:                code_gt = f.read().replace(b'  </Action>\r\n</Project>', code_gt_tong)            with open(file, 'wb') as f:                f.write(code_gt)        if ID_SKIN == "11620":            with open('Data/Code/CODE_GT_11620.xml', 'rb') as f:                                code_gt1 = f.read()            code_gt_tong = code_gt1            code_gt_tong = code_gt_tong.replace(b'ID_SKIN', ID_SKIN.encode()).replace(b'ID_HERO', ID_HERO.encode()).replace(b'NAME_HERO', NAME_HERO.encode()).replace(b'GuidStopTrack1', GuidStopTrack).replace(b'GuidStopTrack2', GuidStopTrack2)            with open(file, 'rb') as f:                code_gt = f.read().replace(b'  </Action>\r\n</Project>', code_gt_tong)            with open(file, 'wb') as f:                f.write(code_gt)                                                        if ID_SKIN not in ["15710", "15015", "11620"]:                        with open(file, 'rb') as f:                if ID_SKIN in ID_HD:            	    code_gt_tong = code_gt_tong.replace(b".prefab", b"_HD")                code_gt = f.read().replace(b'  </Action>\r\n</Project>', code_gt_tong)            with open(file, 'wb') as f:                f.write(code_gt)                          with open(file, 'rb') as f:            rpl = f.read()                tracks = rpl.split(b"</Track>")        modified_tracks = []                for track in tracks:            if any(x in track for x in [b'Anim', b'PlayAnimDuration', b'PlayAnimationTick', b'SetAnimationParamsTick', b'TriggerParticle', b'STOP TRACK']):                prefix = ID_SKIN[:3]                if code_duoi_giatoc.lower() == b'jiasu_tongyong_01' or ID_SKIN in ["15015", "13311", "15004", "11620"]:                    pattern = f'<SkinOrAvatarList id="{ID_SKIN}" />'.encode()                    if pattern in track:                        lines = [f'      <SkinOrAvatarList id="{prefix}{i:02}" />'.encode() for i in range(46)]                        if ID_SKIN not in [f"{prefix}{i:02}" for i in range(46)]:                            lines.append(f'      <SkinOrAvatarList id="{ID_SKIN}" />'.encode())                        generated_block = b'\r\n'.join(lines)                        track = track.replace(pattern, generated_block)                                        if b'STOP TRACK' in track:                    pattern = f'<SkinOrAvatarList id="{ID_SKIN}" />'.encode()                    if pattern in track:                        lines = [f'      <SkinOrAvatarList id="{prefix}{i:02}" />'.encode() for i in range(46)]                        if ID_SKIN not in [f"{prefix}{i:02}" for i in range(46)]:                            lines.append(f'      <SkinOrAvatarList id="{ID_SKIN}" />'.encode())                        generated_block = b'\r\n'.join(lines)                        track = track.replace(pattern, generated_block)                                        else:                    pattern = b'<SkinOrAvatarList id="' + ID_SKIN.encode()                    replace_prefix = b'<SkinOrAvatarList id="' + ID_SKIN[:3].encode() + b"00"                    track = track.replace(pattern, replace_prefix)                                        modified_tracks.append(track + b"</Track>")            else:                modified_tracks.append(track + b"</Track>")        rpl = b"".join(modified_tracks)        if rpl.endswith(b"</Track>"):            rpl = rpl[:-8]                with open(file, 'wb') as f:            f.write(rpl)        """with open(file, 'rb') as f:            rpl = f.read()                tracks = rpl.split(b"</Track>")        modified_tracks = []                for track in tracks:            if b'skinIdArray' in track and f'<int value="{ID_SKIN}" />'.encode() in track:                pattern = f'<int value="{ID_SKIN}" />'.encode()                lines = [                    f'        <int value="{ID_SKIN[:3]}{i:02}" />'.encode()                    for i in range(46)                ]                generated_block = b"\r\n".join(lines)                track = track.replace(pattern, generated_block)                    modified_tracks.append(track + b"</Track>")                rpl = b"".join(modified_tracks)                if rpl.endswith(b"</Track>"):            rpl = rpl[:-8]                with open(file, 'wb') as f:            f.write(rpl)"""                    """with open(file, 'rb') as f:            rpl = f.read()        tracks = rpl.split(b"</Track>")        modified_tracks = []        for track in tracks:            if b'<int name="skinId" value="' + ID_SKIN.encode() in track:                track = (track.replace(b'CheckSkinId', b'CheckHeroId').replace(b'<int name="skinId" value="' + ID_SKIN.encode(), b'<int name="heroId" value="' + ID_SKIN[:3].encode()).replace(b'<bool name="bEqual" value="false" refParamName="" useRefParam="false" />\r\n        <bool name="bSkipLogicCheck" value="true" refParamName="" useRefParam="false" />', b''))                modified_tracks.append(track + b"</Track>")                         else:                                                                              modified_tracks.append(track + b"</Track>")                                 rpl = b"".join(modified_tracks)            if rpl.endswith(b"</Track>"):            rpl = rpl[:-8]                                               with open(file, 'wb') as f:            f.write(rpl)"""                    with open(file, 'rb') as f:            rpl = f.read()        tracks = rpl.split(b"</Track>")        modified_tracks = []        for track in tracks:            if b'/jiasu_tongyong_01,' in track:                track = (track.replace(b'jiasu_tongyong_01,', b'jiasu_tongyong_01.prefab" refParamName="" useRefParam="false" />\r\n        <Vector3 name="bindPosOffset" x="0.000" y="0.700" z="-0.600" refParamName="" useRefParam="false" />\r\n      </Event>\r\n' + b'      <SkinOrAvatarList id="' + ID_SKIN[:3].encode() + b"00" + b'" />\r\n    </Track>\r\n    <Track trackName="TriggerParticle0" eventType="TriggerParticle" guid="NAME_HERO/ID_SKIN" enabled="true" useRefParam="false" refParamName="" r="0.000" g="0.000" b="0.000" execOnForceStopped="false" execOnActionCompleted="false" stopAfterLastEvent="true" SkinAvatarFilterType="9">\r\n      <Event eventName="TriggerParticle" time="0.000" length="5.000" isDuration="true">\r\n        <TemplateObject name="targetId" id="1" objectName="target" isTemp="false" refParamName="" useRefParam="false" />\r\n        <TemplateObject name="objectSpaceId" id="1" objectName="target" isTemp="false" refParamName="" useRefParam="false" />\r\n        <String name="parentResourceName" value="" refParamName="" useRefParam="false"/>\r\n        <String name="resourceName" value="Prefab_Skill_Effects/Hero_Skill_Effects/NAME_HERO/ID_SKIN/').replace(b'ID_SKIN', ID_SKIN.encode()).replace(b'ID_HERO', ID_HERO.encode()).replace(b'NAME_HERO', NAME_HERO.encode()))                                                         modified_tracks.append(track + b"</Track>")                         else:                                                                              modified_tracks.append(track + b"</Track>")                                 rpl = b"".join(modified_tracks)            if rpl.endswith(b"</Track>"):            rpl = rpl[:-8]                                               with open(file, 'wb') as f:            f.write(rpl)      if ID_SKIN in ["11620"]:        with open(DaofengSprint_Mod, "rb") as f:            data = f.read()        data = data.replace(b"Sprint_end", b"11620/Awaken/Dance16_Sprint_end")        with open(DaofengSprint_Mod, "wb") as f:           f.write(data)           